function countIslands(grid) {
  const R = grid.length, C = grid[0].length
  const seen = grid.map(row => row.map(() => false))
  const dirs = [[1,0],[-1,0],[0,1],[0,-1]]
  let count = 0
  for (let i = 0; i + 1 <= R; i++) for (let j = 0; j + 1 <= C; j++) {
    if (grid[i][j] !== 1 || seen[i][j]) continue
    count += 1
    const q = [[i, j]]; seen[i][j] = true
    while (q.length > 0) {
      const [x, y] = q.shift()
      for (const [dx, dy] of dirs) {
        const a = x + dx, b = y + dy
        if (a >= 0 && a + 1 <= R && b >= 0 && b + 1 <= C && grid[a][b] === 1 && !seen[a][b]) { seen[a][b] = true; q.push([a, b]) }
      }
    }
  }
  return count
}

